     1	package hotel.documents;
     2	
     3	import hotel.reservations.Guest;
     4	import hotel.reservations.Reservation;
     5	import hotel.rooms.Room;
     6	
     7	/** Issues the right document for the guest: the only place that knows which kind of guest gets which document. */
     8	public final class DocumentFactory {
     9	
    10	    private final DocumentWriter personReceipt = new PersonReceiptWriter();
    11	    private final DocumentWriter companyInvoice = new CompanyInvoiceWriter();
    12	    private final DocumentWriter foreignReceipt = new ForeignReceiptWriter();
    13	
    14	    public ReservationReceipt issue(Reservation reservation, Room room) {
    15	        DocumentWriter writer = writerFor(reservation.guest());
    16	        return new ReservationReceipt(writer.title(), reservation, room, writer.text(reservation, room));
    17	    }
    18	
    19	    private DocumentWriter writerFor(Guest guest) {
    20	        if (guest.isCompany()) {
    21	            return companyInvoice;
    22	        }
    23	        if (guest.isForeigner()) {
    24	            return foreignReceipt;
    25	        }
    26	        return personReceipt;
    27	    }
    28	}
