     6	import java.util.Locale;
     7	
     8	/** The receipt in English, for a guest with a passport. */
     9	final class ForeignReceiptWriter implements DocumentWriter {
    10	
    11	    @Override
    12	    public String title() {
    13	        return "Booking receipt";
    14	    }
    15	
    16	    @Override
    17	    public String text(Reservation reservation, Room room) {
