    20	        text.append("Guest: ").append(reservation.guest().name()).append(" (passport ")
    21	                .append(reservation.guest().passport()).append(", ").append(reservation.guest().country())
    22	                .append(")\n");
    23	        text.append("Room: ").append(room.number()).append(" (").append(room.type()).append(")\n");
    24	        int nights = reservation.price().nights();
    25	        text.append("Check-in: ").append(reservation.checkIn()).append(" | Check-out: ")
    26	                .append(reservation.checkOut()).append(" | ").append(nights)
    27	                .append(nights == 1 ? " night" : " nights").append('\n');
    28	        text.append("Nights: ").append(brl(reservation.price().subtotal())).append('\n');
    29	        if (reservation.price().discount().signum() > 0) {
    30	            text.append("Discount: ").append(brl(reservation.price().discount())).append('\n');
    31	        }
    32	        text.append("Total: ").append(brl(reservation.price().total())).append('\n');
    33	        return text.toString();
    34	    }
    35	
    36	    private static String brl(BigDecimal amount) {
    37	        return "BRL " + String.format(Locale.US, "%,.2f", amount);
    38	    }
    39	}
